/* The PNG stores TLF1 bytes, not image frames. Data URLs allow local canvas reads.
 * Layout: dimensions/counts, mask, coefficients, colour ratios, delta-coded mean
 * (16-bit), then 15 light patterns (8-bit).
 */
(() => {
  'use strict';
  const round = Math.round;
  const PACKED_PATTERNS = '';
  let pending;

  async function decode() {
    const image = new Image();
    image.decoding = 'async';
    image.src = `data:image/png;base64,${PACKED_PATTERNS}`;
    await image.decode();
    const surface = document.createElement('canvas');
    surface.width = image.width;
    surface.height = image.height;
    const reader = surface.getContext('2d', { willReadFrequently: true });
    reader.drawImage(image, 0, 0);
    const rgba = reader.getImageData(0, 0, image.width, image.height).data;
    const packed = new Uint8Array(image.width * image.height * 3);
    for (let source = 0, target = 0; target < packed.length; source += 4) {
      packed[target++] = rgba[source];
      packed[target++] = rgba[source + 1];
      packed[target++] = rgba[source + 2];
    }
    surface.width = surface.height = 1;
    const header = new DataView(packed.buffer);
    if (header.getUint32(0, false) !== 0x544c4631) throw new Error('Invalid tree light data.');
    const width = header.getUint16(4, true), height = header.getUint16(6, true);
    const count = header.getUint16(8, true), rank = header.getUint16(10, true);
    const support = header.getUint32(12, true), quant = header.getFloat32(16, true);
    const meanPrecision = header.getFloat32(20, true), length = header.getUint32(24, true);
    const stride = support * 4;
    const expected = 32 + width * height + rank * count * 4 + (rank + 1) * 12 + stride * (rank + 2);
    if (width !== 316 || height !== 403 || count !== 96 || rank !== 15 ||
        support > width * height || length !== expected || length > packed.length) {
      throw new Error('Incomplete tree light data.');
    }

    const positions = new Uint32Array(support);
    let offset = 32, cursor = 0;
    for (let pixel = 0; pixel < width * height; pixel++) {
      if (packed[offset++]) positions[cursor++] = pixel * 4;
    }
    if (cursor !== support) throw new Error('Invalid tree light mask.');
    const coefficients = new Float32Array(rank * count);
    for (let component = 0; component < rank; component++) {
      for (let frame = 0; frame < count; frame++) {
        coefficients[frame * rank + component] = header.getFloat32(offset, true) / 8;
        offset += 4;
      }
    }
    const ratios = new Float32Array((rank + 1) * 3);
    for (let i = 0; i < ratios.length; i++, offset += 4) ratios[i] = header.getFloat32(offset, true);
    const mean = new Int16Array(stride), patterns = new Int16Array(stride * rank);
    const previous = new Int16Array(4);
    const low = offset, high = low + stride;
    offset += stride * 2;
    for (let pixel = 0; pixel < support; pixel++) {
      const index = pixel * 4;
      for (let channel = 0; channel < 4; channel++) {
        const i = index + channel;
        previous[channel] += packed[low + i] | packed[high + i] << 8;
      }
      const red = previous[0];
      mean[index] = round(red * meanPrecision * 8);
      for (let channel = 1; channel < 4; channel++) {
        mean[index + channel] = round((previous[channel] + red * ratios[channel - 1]) * meanPrecision * 8);
      }
    }
    for (let component = 0; component < rank; component++) {
      previous.fill(0);
      const start = component * stride, ratio = (component + 1) * 3;
      for (let pixel = 0; pixel < support; pixel++) {
        const index = start + pixel * 4;
        for (let channel = 0; channel < 4; channel++) {
          const value = (previous[channel] + packed[offset++]) & 255;
          previous[channel] = value < 128 ? value : value - 256;
        }
        const red = previous[0];
        patterns[index] = round(red * quant * 8);
        for (let channel = 1; channel < 4; channel++) {
          patterns[index + channel] = round((previous[channel] + red * ratios[ratio + channel - 1]) * quant * 8);
        }
      }
      if (component % 3 === 2) await new Promise(resolve => setTimeout(resolve, 0));
    }

    return {
      width, height, count,
      createPainter(context) {
        const framePixels = context.createImageData(width, height), pixels = framePixels.data;
        return frame => {
          const row = frame * rank;
          for (let pixel = 0; pixel < support; pixel++) {
            const index = pixel * 4;
            let red = mean[index] / 8, green = mean[index + 1] / 8;
            let blue = mean[index + 2] / 8, alpha = mean[index + 3] / 8;
            for (let component = 0; component < rank; component++) {
              const at = component * stride + index, weight = coefficients[row + component];
              red += patterns[at] * weight;
              green += patterns[at + 1] * weight;
              blue += patterns[at + 2] * weight;
              alpha += patterns[at + 3] * weight;
            }
            const target = positions[pixel], roundedAlpha = round(alpha);
            const a = roundedAlpha < 0 ? 0 : roundedAlpha > 255 ? 255 : roundedAlpha;
            pixels[target + 3] = a;
            const unpremultiply = a ? 255 / a : 0;
            const r = round(red), g = round(green), b = round(blue);
            pixels[target] = (r < 0 ? 0 : r > a ? a : r) * unpremultiply;
            pixels[target + 1] = (g < 0 ? 0 : g > a ? a : g) * unpremultiply;
            pixels[target + 2] = (b < 0 ? 0 : b > a ? a : b) * unpremultiply;
          }
          context.putImageData(framePixels, 0, 0);
        };
      }
    };
  }

  window.loadTreeLightPixels = () => pending || (pending = decode());
})();
